// TestUploadFixtures_FeedUploadPart (brief M3-09 Design note 20 a): a human uploadPart with
// with.fixture sends the generated bytes with their Content-Digest, createUpload gets their size
// and SHA-256, and a fixture on another operation or an unknown name is refused.
func TestUploadFixtures_FeedUploadPart(t *testing.T) {
	t.Parallel()
	for name, gen := range uploadFixtures {
		t.Run(name, func(t *testing.T) {
			t.Parallel()
			want := gen()
			sum := sha256.Sum256(want)
			body, header, err := applyFixture("uploadPart", map[string]any{"file_id": "f", "part_number": 1, "fixture": name})
			if err != nil {
				t.Fatal(err)
			}
			got, ok := body.([]byte)
			if !ok || !bytes.Equal(got, want) {
				t.Fatalf("uploadPart body is %T, not the generated fixture", body)
			}
			if header.Get("Content-Type") != "application/octet-stream" ||
				header.Get("Content-Digest") != "sha-256=:"+base64.StdEncoding.EncodeToString(sum[:])+":" {
				t.Fatalf("uploadPart headers %v", header)
			}
			with := map[string]any{"channel_id": "c", "name": "x", "fixture": name}
			created, _, err := applyFixture("createUpload", with)
			if err != nil {
				t.Fatal(err)
			}
			m, _ := created.(map[string]any)
			if m["size_bytes"] != len(want) || m["sha256"] != hex.EncodeToString(sum[:]) {
				t.Fatalf("createUpload body %v", m)
			}
			if _, left := m["fixture"]; left {
				t.Fatal("the fixture name stays in the body")
			}
		})
	}
	if _, _, err := applyFixture("uploadPart", map[string]any{"fixture": "speech.wav"}); err == nil {
		t.Fatal("an unknown fixture was accepted")
	}
	if _, _, err := applyFixture("createMessage", map[string]any{"fixture": "text_note"}); err == nil {
		t.Fatal("a fixture on createMessage was accepted")
	}
}

// TestUploadFixtures_VoiceIsMP4Audio: the generated voice file is what the server reads as MP4
// audio: the pinned type detector names an MP4 audio type of the file module, and the box reader
// finds the mvhd duration and no video track.
func TestUploadFixtures_VoiceIsMP4Audio(t *testing.T) {
	t.Parallel()
	data := uploadFixtures["voice_m4a"]()
	mime := mimetype.Detector{}.Detect(data)
	if !domain.HasContainerMetadata(mime) || !strings.HasPrefix(mime, "audio/") {
		t.Fatalf("detected %q, want an MP4 audio type", mime)
	}
	info, err := isobmff.ReadMovieInfo(bytes.NewReader(data), int64(len(data)))
	if err != nil {
		t.Fatal(err)
	}
	if !info.HasDuration || info.DurationMS != voiceSeconds*1000 || info.HasSize {
		t.Fatalf("movie info %+v, want %d ms and no video size", info, voiceSeconds*1000)
	}
	if mime := (mimetype.Detector{}).Detect(uploadFixtures["text_note"]()); !strings.HasPrefix(mime, "text/plain") {
		t.Fatalf("the text fixture is detected as %q", mime)
	}
}

// TestFileJobs_Settled: run_jobs of a file kind waits until no job of the kind is open in
// River's table and counts each completed job once; a discarded job fails the step.
func TestFileJobs_Settled(t *testing.T) {
	t.Parallel()
	seen := map[int64]bool{}
	open := fakeRows{all: []map[string]any{{"id": float64(1), "state": "completed"}, {"id": float64(2), "state": "running"}}}
	ran, settled, err := fileJobsSettled(t.Context(), open, "river", "files.scan", seen)
	if err != nil || settled || ran != 0 {
		t.Fatalf("with a running job: ran %d settled %v err %v", ran, settled, err)
	}
	done := fakeRows{all: []map[string]any{{"id": float64(1), "state": "completed"}, {"id": float64(2), "state": "completed"}}}
	ran, settled, err = fileJobsSettled(t.Context(), done, "river", "files.scan", seen)
	if err != nil || !settled || ran != 2 {
		t.Fatalf("all completed: ran %d settled %v err %v", ran, settled, err)
	}
	ran, settled, err = fileJobsSettled(t.Context(), done, "river", "files.scan", seen)
	if err != nil || !settled || ran != 0 {
		t.Fatalf("the same jobs again: ran %d settled %v err %v", ran, settled, err)
	}
	failed := fakeRows{all: []map[string]any{{"id": float64(3), "state": "discarded"}}}
	if _, _, err := fileJobsSettled(t.Context(), failed, "river", "files.transcribe", seen); err == nil {
		t.Fatal("a discarded job passed")
	}
}

// TestFileCheck_NeverReadsTheText: the check file reads id, upload_state, scan_status,
// transcript_status and transcript_source only; neither the transcript nor the name reaches a
// failure message.
func TestFileCheck_NeverReadsTheText(t *testing.T) {
	t.Parallel()
	sql, _, err := checkQuery("file", "f1", nil)
	if err != nil {
		t.Fatal(err)
	}
	for _, col := range fileCheckColumns {
		if !strings.Contains(sql, "'"+col+"', t."+col) {
			t.Errorf("the check file does not read %s: %s", col, sql)
		}
	}
	for _, secret := range []string{"transcript_text", "original_name", "to_jsonb(t) FROM", "search_vector"} {
		if strings.Contains(sql, secret) {
			t.Errorf("the check file reads %s: %s", secret, sql)
		}
	}
}

// TestToAnswer_StatusIsTheHTTPStatus: a body member named status (the Agent of updateAgent says
// "active") never hides the HTTP status an expectation compares.
func TestToAnswer_StatusIsTheHTTPStatus(t *testing.T) {
	t.Parallel()
	a := toAnswer(200, []byte(`{"id":"a1","status":"active"}`), http.Header{})
	if a["status"] != 200 || a["id"] != "a1" {
		t.Fatalf("answer %v, want the HTTP status 200", a)
	}
	p := toAnswer(412, []byte(`{"status":412,"code":"version_conflict"}`), http.Header{})
	if p["status"] != 412 || p["code"] != "version_conflict" {
		t.Fatalf("problem answer %v", p)
	}
}
